{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Benztropine, a close N-methyl tropane analogue, showed clear brain uptake in human and baboon PET, demonstrating that this tropane scaffold can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tropisetron, a tropine ester with an N-methyl tropane core, reached a brain/plasma ratio of 2.5 in mice, directly supporting high CNS penetration for the query's tropane ester framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "N-methyl tropane analogues such as AHN 1-055 readily and rapidly crossed the BBB in rats with brain-to-plasma ratios at least 2-fold higher than cocaine, supporting CNS access for the query's tertiary amine tropane.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The tropane-based radiotracer [18F]MCL-322 showed efficient BBB passage with high striatal uptake in rats, reinforcing that tropane esters with N-methyl substitution penetrate the brain well.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Methylphenidate, a structurally related ester-containing tropane-like CNS drug, achieved high brain-to-plasma ratios of 10.6–11.2 in rats, supporting the CNS penetrant nature of this chemical class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an N-methyl tropane ester of tropic acid, closely related to known CNS-penetrant tropanes such as benztropine, tropisetron, and AHN analogues. Multiple direct in vivo brain uptake studies in rodents and primates demonstrate that this scaffold readily crosses the BBB. The only negative evidence involves a quaternary ammonium analogue, which is not applicable to the tertiary amine query.",
  "evidence_gaps": [
    "No direct human CSF or brain PK measurement for the exact query molecule, but close analogues provide strong transferable evidence.",
    "Efflux transporter involvement was not explicitly measured, but multiple in vivo brain uptake studies support net meaningful CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

